### The Modern `SPISettings` API
In modern Arduino firmware, you configure speed, bit order, and SPI mode using `SPISettings` and safe transactions:

```cpp
#include <SPI.h>

const int CHIP_SELECT = 10;

// Configure SPI transaction parameters:
// 1. Clock speed: 4 MHz (4000000 Hz)
// 2. Bit order: MSBFIRST (Most Significant Bit First)
// 3. Mode: SPI_MODE0 (CPOL=0, CPHA=0)
SPISettings sensorSettings(4000000, MSBFIRST, SPI_MODE0);

void setup() {
  Serial.begin(9600);
  pinMode(CHIP_SELECT, OUTPUT);
  digitalWrite(CHIP_SELECT, HIGH);

  SPI.begin();
  Serial.println("SPI Master Configured with SPISettings.");
}

byte readSensorRegister(byte regAddress) {
  // 1. Lock bus and apply hardware settings
  SPI.beginTransaction(sensorSettings);
  digitalWrite(CHIP_SELECT, LOW); // Assert CS

  // 2. Transmit register address; ignore return byte during address phase
  SPI.transfer(regAddress);

  // 3. Transmit dummy byte 0x00 to pump SCK clock pulses and receive data!
  byte sensorData = SPI.transfer(0x00);

  // 4. Release peripheral and release bus lock
  digitalWrite(CHIP_SELECT, HIGH); // De-assert CS
  SPI.endTransaction();

  return sensorData;
}

void loop() {
  byte status = readSensorRegister(0x05); // Read register 0x05
  Serial.print("Sensor Reg 0x05 Value: 0x");
  Serial.println(status, HEX);
  delay(1000);
}
```

### Code Breakdown:
- `SPI.beginTransaction(sensorSettings)`: Configures the ATmega328P SPI hardware registers to the exact speed and mode needed, protecting against interrupts.
- `SPI.transfer(0x00)`: The dummy byte! Shifting out `0x00` generates 8 clock pulses so the peripheral can shift its data byte into the Arduino over MISO.
- `SPI.endTransaction()`: Releases the bus settings so other SPI devices using different modes or clock speeds can run cleanly.
